structureCode.vanilla:
const campo = createSelect({
  id: 'estado',
  name: 'estado',
  placeholder: 'Selecione...',
  // O papel de combobox não aceita nome vindo do próprio conteúdo.
  'aria-label': 'Estado',
  items: [
    { value: 'sp', label: 'São Paulo' },
    { value: 'rj', label: 'Rio de Janeiro' },
  ],
  onValueChange: (valor) => console.log(valor),
});

// Solta o ouvinte de documento e o painel em portal. Idempotente, e
// disparado sozinho quando a raiz sai do documento.
campo.destroy();

extensibilityCode.vanilla:
const campo = createSelect({
  placeholder: 'Selecione...',
  'aria-label': 'Estado',
  items: [
    { type: 'group', label: 'Sudeste', items: [
      { value: 'sp', label: 'São Paulo' },
      { value: 'rj', label: 'Rio de Janeiro' },
    ] },
    { type: 'separator' },
    { type: 'group', label: 'Sul', items: [
      { value: 'rs', label: 'Rio Grande do Sul' },
      { value: 'sc', label: 'Santa Catarina' },
    ] },
  ],
});

customizationCode.web:
/* Largura mínima da lista de opções */
.nds-select-content {
  min-width: 12rem;
}

/* Campo mais alto sem cravar altura — o crescimento vem do padding */
.nds-select-trigger {
  padding-block: var(--spacing-4);
}

